sys_script.script:
(function executeRule(current, previous) {

    var invoiceIds = [];

    // Get current Invoice
    if (current.getValue('invoice')) {
        invoiceIds.push(current.getValue('invoice'));
    }

    // Get previous Invoice if reference changed
    if (previous && previous.getValue('invoice')) {
        var oldInvoiceId = previous.getValue('invoice');

        if (invoiceIds.indexOf(oldInvoiceId) === -1) {
            invoiceIds.push(oldInvoiceId);
        }
    }

    // Recalculate affected Invoices
    for (var i = 0; i < invoiceIds.length; i++) {

        var totalPaid = 0;

        var payment = new GlideRecord('x_2223823_apollo_0_payment');
        payment.addQuery('invoice', invoiceIds[i]);
        payment.addQuery('status', 'succeeded');
        payment.addQuery('kind', '!=', 'refund');
        payment.query();

        while (payment.next()) {
            totalPaid += parseFloat(payment.getValue('amount')) || 0;
        }

        // Get successful refunds separately
        var refunds = new GlideRecord('x_2223823_apollo_0_payment');
        refunds.addQuery('invoice', invoiceIds[i]);
        refunds.addQuery('status', 'succeeded');
        refunds.addQuery('kind', 'refund');
        refunds.query();

        while (refunds.next()) {
            totalPaid -= parseFloat(refunds.getValue('amount')) || 0;
        }

        // Update Invoice
        var invoice = new GlideRecord('x_2223823_apollo_0_invoice');

        if (invoice.get(invoiceIds[i])) {

            var totalAmount = parseFloat(
                invoice.getValue('total_amount')
            ) || 0;

            var balance = totalAmount - totalPaid;

            invoice.setValue('paid_amount', totalPaid);
            invoice.setValue('total_balance', balance);

            invoice.update();
        }
    }

})(current, previous);
